const Redis = require('ioredis');
const redis = new Redis();

// Anti-pattern: one unbounded hash
// HINCRBY user:123:metrics page_views 1
// After 1M days, this hash has 1M fields

// Better: bucket by time
async function recordPageView(userId) {
  const bucket = Math.floor(Date.now() / 86400000); // daily bucket
  const key = 'user:' + userId + ':pv:' + bucket;
  await redis.hincrby(key, 'count', 1);
  await redis.expire(key, 604800); // 7 days
}

using StackExchange.Redis;

var mux = ConnectionMultiplexer.Connect("localhost:6379");
var db = mux.GetDatabase();

// Bad: blocks thread, causes thread-pool starvation
string badValue = db.StringGet("key").ToString();

// Good: async all the way
string goodValue = await db.StringGetAsync("key");

// Bad: new pool per request
public string GetValue(string key)
{
    var mux = ConnectionMultiplexer.Connect("localhost:6379");
    return mux.GetDatabase().StringGet(key).ToString();
}

// Good: shared pool as singleton
public class RedisService
{
    private readonly ConnectionMultiplexer _mux;
    public RedisService()
    {
        _mux = ConnectionMultiplexer.Connect("localhost:6379");
    }
    public async Task<string?> GetAsync(string key)
        => await _mux.GetDatabase().StringGetAsync(key);
}
